/**
 * Branching Scenario: the graph rules, the scoring, and the player's state
 * machine, as pure functions.
 *
 * NO IMPORTS, like every other file in lib/h5p: it can be tested without a
 * browser and without Next.js, and no player has to be read to know what a
 * scenario is worth or whether it is sound.
 *
 * THE RULES HERE ARE THE RULES IN PHP. `analyse()` is a port of
 * App\Services\lms\H5P\BranchingGraph + BranchingPayload, and the two are held
 * together by a golden file (lib/h5p/fixtures/branching-graph-golden.json,
 * generated by the backend test) that both test suites run: if the editor says a
 * scenario is sound and the server refuses to publish it, that test fails, not
 * a teacher.
 *
 * A SCENARIO HERE IS A NORMALISED SHAPE (`BsScenario`): string keys, camelCase,
 * edges as keys. The API's rows (numeric ids, snake_case), the editor's payload
 * (client refs) and a freshly generated draft all become the same thing through
 * `normalizeScenario()`, so the player, the preview and the editor's checks are
 * written once.
 */

// ---------------------------------------------------------------------------
// Vocabulary
// ---------------------------------------------------------------------------

export const BS_NODE_TYPES = ['text', 'branching_question', 'ending'] as const;
export type BsNodeType = (typeof BS_NODE_TYPES)[number];

export const BS_QUALITIES = ['best', 'partial', 'misstep'] as const;
export type BsQuality = (typeof BS_QUALITIES)[number];

export const BS_PURPOSES = [
  'situation', 'explanation', 'example', 'investigate', 'predict', 'apply',
  'check', 'consequence', 'remedial', 'reflection', 'summary',
] as const;
export type BsPurpose = (typeof BS_PURPOSES)[number];

export const BS_NODE_LABELS: Record<BsNodeType, string> = {
  text: 'Screen',
  branching_question: 'Decision',
  ending: 'Ending',
};

export const BS_PURPOSE_LABELS: Record<string, string> = {
  situation: 'Situation',
  explanation: 'Explanation',
  example: 'Example',
  investigate: 'Investigate',
  predict: 'Predict',
  apply: 'Apply',
  check: 'Knowledge check',
  consequence: 'Consequence',
  remedial: 'Rethink',
  reflection: 'Reflection',
  summary: 'Summary',
};

export const BS_QUALITY_LABELS: Record<BsQuality, string> = {
  best: 'Sound',
  partial: 'Partly right',
  misstep: 'Needs rethinking',
};

export type BsScoring = 'no-score' | 'static-end-score';

// ---------------------------------------------------------------------------
// Shapes
// ---------------------------------------------------------------------------

export interface BsChoice {
  text: string;
  next: string | null;
  quality: BsQuality | null;
  feedbackTitle: string;
  feedbackText: string;
  feedbackImage: string;
  feedbackImageAlt: string;
}

export interface BsNode {
  key: string;
  type: BsNodeType;
  purpose: string | null;
  title: string;
  showTitle: boolean;
  /** HTML. A screen's content, a decision's question, an ending's closing words. */
  body: string;
  mediaPath: string;
  mediaAlt: string;
  proceedLabel: string;
  next: string | null;
  choices: BsChoice[];
  score: number;
  conceptId: number | null;
  questionId: number | null;
}

export interface BsScenario {
  title: string;
  description: string;
  startTitle: string;
  startSubtitle: string;
  startImage: string;
  startImageAlt: string;
  objectives: string[];
  scoring: BsScoring;
  passPercentage: number;
  backNavigation: boolean;
  randomizeChoices: boolean;
  nodes: BsNode[];
}

/** What the API's rows and the editor's payload both look like, loosely. */
export interface RawOption {
  text?: string | null;
  next_node_id?: number | string | null;
  next_ref?: string | null;
  quality?: string | null;
  feedback_title?: string | null;
  feedback_text?: string | null;
  feedback_image?: string | null;
  feedback_image_alt?: string | null;
}

export interface RawNode {
  id?: number | string;
  ref?: string;
  node_type?: string;
  purpose?: string | null;
  title?: string | null;
  show_title?: boolean | number | null;
  body?: string | null;
  media_path?: string | null;
  media_alt?: string | null;
  proceed_button_text?: string | null;
  next_node_id?: number | string | null;
  next_ref?: string | null;
  options?: RawOption[] | null;
  score?: number | null;
  concept_id?: number | null;
  source_question_id?: number | null;
}

export interface RawScenario {
  title?: string | null;
  description?: string | null;
  start_title?: string | null;
  start_subtitle?: string | null;
  start_image?: string | null;
  start_image_alt?: string | null;
  learning_objectives?: string[] | null;
  scoring_option?: string | null;
  pass_percentage?: number | null;
  enable_backwards_navigation?: boolean | number | null;
  randomize_alternatives?: boolean | number | null;
  nodes?: RawNode[] | null;
}

const str = (value: unknown): string => (typeof value === 'string' ? value : value == null ? '' : String(value));

const refOf = (ref: string | null | undefined, id: number | string | null | undefined): string | null => {
  if (ref != null && ref !== '') return String(ref);
  if (id != null && id !== '') return String(id);
  return null;
};

function qualityOf(value: unknown): BsQuality | null {
  return (BS_QUALITIES as readonly string[]).includes(String(value)) ? (value as BsQuality) : null;
}

/**
 * Rows from the API, a saved payload, or a generated draft -> one shape.
 *
 * A node is identified by its client `ref` when it has one and by its row `id`
 * otherwise, and its edges likewise, so the same function reads both.
 */
export function normalizeScenario(raw: RawScenario): BsScenario {
  const nodes: BsNode[] = (raw.nodes ?? []).map((n, index) => {
    const type: BsNodeType = (BS_NODE_TYPES as readonly string[]).includes(str(n.node_type))
      ? (n.node_type as BsNodeType)
      : 'text';

    return {
      key: refOf(n.ref, n.id) ?? `node-${index}`,
      type,
      purpose: n.purpose ? String(n.purpose) : null,
      title: str(n.title),
      showTitle: n.show_title == null ? true : Boolean(n.show_title),
      body: str(n.body),
      mediaPath: str(n.media_path),
      mediaAlt: str(n.media_alt),
      proceedLabel: str(n.proceed_button_text),
      next: type === 'text' ? refOf(n.next_ref, n.next_node_id) : null,
      choices:
        type === 'branching_question'
          ? (n.options ?? []).map((o) => ({
              text: str(o.text),
              next: refOf(o.next_ref, o.next_node_id),
              quality: qualityOf(o.quality),
              feedbackTitle: str(o.feedback_title),
              feedbackText: str(o.feedback_text),
              feedbackImage: str(o.feedback_image),
              feedbackImageAlt: str(o.feedback_image_alt),
            }))
          : [],
      score: type === 'ending' ? Math.max(0, Math.round(Number(n.score) || 0)) : 0,
      conceptId: n.concept_id ?? null,
      questionId: n.source_question_id ?? null,
    };
  });

  return {
    title: str(raw.title),
    description: str(raw.description),
    startTitle: str(raw.start_title) || str(raw.title),
    startSubtitle: str(raw.start_subtitle),
    startImage: str(raw.start_image),
    startImageAlt: str(raw.start_image_alt),
    objectives: (raw.learning_objectives ?? []).map(str).filter((o) => o.trim() !== ''),
    scoring: raw.scoring_option === 'no-score' ? 'no-score' : 'static-end-score',
    passPercentage: raw.pass_percentage == null ? 60 : Math.max(0, Math.min(100, Number(raw.pass_percentage))),
    backNavigation: raw.enable_backwards_navigation == null ? true : Boolean(raw.enable_backwards_navigation),
    randomizeChoices: Boolean(raw.randomize_alternatives),
    nodes,
  };
}

// ---------------------------------------------------------------------------
// Text helpers
// ---------------------------------------------------------------------------

/** Visible text of an HTML fragment, whitespace collapsed. */
export function plainText(html: unknown): string {
  return str(html)
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#0?39;/g, "'")
    .replace(/\s+/g, ' ')
    .trim();
}

/** "Step 3 (Testing the water)" — or "Step 3" for an untitled one. */
export function nodeLabel(node: Pick<BsNode, 'title'>, index: number): string {
  const title = node.title.trim();
  return title !== '' ? `Step ${index + 1} (${title})` : `Step ${index + 1}`;
}

// ---------------------------------------------------------------------------
// The graph
// ---------------------------------------------------------------------------

export const PATH_CAP = 5000;

export interface BsIssue {
  level: 'error' | 'warning';
  code: string;
  node: string | null;
  message: string;
}

export interface BsStats {
  nodes: number;
  screens: number;
  decisions: number;
  endings: number;
  paths: number;
  paths_capped: boolean;
  longest_path: number;
  shortest_path: number;
  endings_reached: number;
  acyclic: boolean;
}

export interface BsAnalysis {
  errors: BsIssue[];
  warnings: BsIssue[];
  stats: BsStats;
}

function targetsOf(node: BsNode): (string | null)[] {
  if (node.type === 'text') return [node.next];
  if (node.type === 'branching_question') return node.choices.map((c) => c.next);
  return [];
}

function edgesOf(nodes: BsNode[]): Map<string, string[]> {
  const keys = new Set(nodes.map((n) => n.key));
  const edges = new Map<string, string[]>();
  for (const node of nodes) {
    edges.set(
      node.key,
      targetsOf(node)
        .filter((t): t is string => t != null && t !== '' && keys.has(t))
        // A screen leading to itself is reported as an error of its own and is
        // not an edge, as on the server. (A decision may lead back to itself.)
        .filter((t) => !(node.type === 'text' && t === node.key))
    );
  }
  return edges;
}

function reachableFrom(start: string, edges: Map<string, string[]>): Set<string> {
  const seen = new Set<string>([start]);
  const stack = [start];
  while (stack.length > 0) {
    const key = stack.pop() as string;
    for (const next of edges.get(key) ?? []) {
      if (!seen.has(next)) {
        seen.add(next);
        stack.push(next);
      }
    }
  }
  return seen;
}

function canReachEnding(nodes: BsNode[], edges: Map<string, string[]>): Set<string> {
  const reverse = new Map<string, string[]>();
  for (const [from, to] of edges) {
    for (const t of to) reverse.set(t, [...(reverse.get(t) ?? []), from]);
  }
  const ok = new Set<string>();
  const stack: string[] = [];
  for (const node of nodes) {
    if (node.type === 'ending') {
      ok.add(node.key);
      stack.push(node.key);
    }
  }
  while (stack.length > 0) {
    const key = stack.pop() as string;
    for (const from of reverse.get(key) ?? []) {
      if (!ok.has(from)) {
        ok.add(from);
        stack.push(from);
      }
    }
  }
  return ok;
}

function isAcyclic(edges: Map<string, string[]>): boolean {
  const state = new Map<string, 1 | 2>();
  const visit = (key: string): boolean => {
    state.set(key, 1);
    for (const next of edges.get(key) ?? []) {
      if (state.get(next) === 1) return false;
      if (state.get(next) === undefined && !visit(next)) return false;
    }
    state.set(key, 2);
    return true;
  };
  for (const key of edges.keys()) {
    if (state.get(key) === undefined && !visit(key)) return false;
  }
  return true;
}

/**
 * Every simple path (no node twice) from the first node to an ending, as lists
 * of node keys. Capped, so a pathological tree cannot hang the editor.
 */
export function enumeratePaths(nodes: BsNode[], cap = PATH_CAP): string[][] {
  if (nodes.length === 0) return [];
  const byKey = new Map(nodes.map((n) => [n.key, n]));
  const edges = edgesOf(nodes);
  const out: string[][] = [];

  const walk = (key: string, path: string[]): void => {
    if (out.length >= cap) return;
    const here = [...path, key];
    if (byKey.get(key)?.type === 'ending') {
      out.push(here);
      return;
    }
    for (const next of new Set(edges.get(key) ?? [])) {
      if (!here.includes(next)) walk(next, here);
    }
  };
  walk(nodes[0].key, []);

  return out;
}

/** Content a learner would find missing. `strict` marks problems that block only at publish. */
interface ContentProblem extends BsIssue {
  strict: boolean;
}

function contentProblems(nodes: BsNode[]): ContentProblem[] {
  const problems: ContentProblem[] = [];
  const add = (code: string, node: BsNode, message: string, level: 'error' | 'warning' = 'error', strict = false) =>
    problems.push({ level, code, node: node.key, message, strict });

  nodes.forEach((node, i) => {
    const name = nodeLabel(node, i);
    const hasBody = plainText(node.body) !== '';
    const hasMedia = node.mediaPath.trim() !== '';

    if (hasMedia && node.mediaAlt.trim() === '') {
      add('missing_alt', node, `${name} has a picture with no description. Add alt text so it can be read aloud.`, 'error', true);
    }
    if (node.type === 'text' && !hasBody && !hasMedia) {
      add('empty_screen', node, `${name} has no text and no picture.`);
    }
    if (node.type === 'branching_question') {
      if (!hasBody) add('empty_question', node, `${name} has no question for the learner to answer.`);
      node.choices.forEach((choice, j) => {
        const n = j + 1;
        if (choice.text.trim() === '') add('empty_choice', node, `Choice ${n} of ${name} has no text.`);
        if (plainText(choice.feedbackText) === '' && plainText(choice.feedbackTitle) === '') {
          add('no_feedback', node, `Choice ${n} of ${name} does not say what happens or why.`, 'warning');
        }
        if (choice.feedbackImage.trim() !== '' && choice.feedbackImageAlt.trim() === '') {
          add('missing_alt', node, `The picture in the feedback for choice ${n} of ${name} has no description.`, 'error', true);
        }
      });
    }
    if (node.type === 'ending' && plainText(node.title) === '' && !hasBody) {
      add('empty_ending', node, `${name} has no title and no closing words.`);
    }
  });

  return problems;
}

/**
 * Is anything wrong with this scenario that a learner would hit?
 *
 * `strict` is the publish standard: problems marked strict (a picture with no
 * description) are errors there and warnings in a draft.
 */
export function analyse(scenario: BsScenario | BsNode[], strict = true): BsAnalysis {
  const nodes = Array.isArray(scenario) ? scenario : scenario.nodes;
  const errors: BsIssue[] = [];
  const warnings: BsIssue[] = [];
  const add = (into: BsIssue[], level: 'error' | 'warning', code: string, node: string | null, message: string) =>
    into.push({ level, code, node, message });

  if (nodes.length === 0) {
    add(errors, 'error', 'empty', null, 'Add at least one step before publishing.');
    return {
      errors,
      warnings,
      stats: {
        nodes: 0, screens: 0, decisions: 0, endings: 0, paths: 0, paths_capped: false,
        longest_path: 0, shortest_path: 0, endings_reached: 0, acyclic: true,
      },
    };
  }

  const byKey = new Map<string, BsNode>();
  nodes.forEach((n) => {
    if (byKey.has(n.key)) add(errors, 'error', 'duplicate_key', n.key, `Two steps share the same id (${n.key}).`);
    byKey.set(n.key, n);
  });
  const label = (key: string) => nodeLabel(byKey.get(key) as BsNode, nodes.findIndex((n) => n.key === key));

  const startKey = nodes[0].key;
  if (nodes[0].type === 'ending') {
    add(errors, 'error', 'start_is_ending', startKey, 'The first step is an ending. A scenario has to begin with content or a decision.');
  }

  const endings = nodes.filter((n) => n.type === 'ending');
  if (endings.length === 0) {
    add(errors, 'error', 'no_ending', null, 'Add at least one ending. Every path has to finish somewhere.');
  } else if (endings.length === 1) {
    add(warnings, 'warning', 'single_ending', null, 'There is only one ending, so every choice leads to the same place. Add an ending for a less successful path.');
  }

  for (const node of nodes) {
    const key = node.key;
    if (node.type === 'text') {
      if (node.next == null || node.next === '') {
        add(errors, 'error', 'missing_next', key, `${label(key)} does not lead anywhere. Choose the step that comes next.`);
      } else if (!byKey.has(node.next)) {
        add(errors, 'error', 'bad_target', key, `${label(key)} leads to a step that does not exist.`);
      } else if (node.next === key) {
        add(errors, 'error', 'self_loop', key, `${label(key)} leads back to itself.`);
      }
    } else if (node.type === 'branching_question') {
      if (node.choices.length < 2) {
        add(errors, 'error', 'too_few_choices', key, `${label(key)} needs at least two choices; with one there is no decision to make.`);
      }
      node.choices.forEach((choice, i) => {
        if (choice.next == null || choice.next === '') {
          add(errors, 'error', 'missing_next', key, `Choice ${i + 1} of ${label(key)} does not lead anywhere.`);
        } else if (!byKey.has(choice.next)) {
          add(errors, 'error', 'bad_target', key, `Choice ${i + 1} of ${label(key)} leads to a step that does not exist.`);
        }
      });
      const distinct = new Set(node.choices.map((c) => c.next).filter((t) => t != null && t !== ''));
      if (node.choices.length >= 2 && distinct.size === 1 && node.questionId == null) {
        add(warnings, 'warning', 'single_destination', key, `Every choice in ${label(key)} leads to the same step, so the decision does not change the path.`);
      }
    }
  }

  const edges = edgesOf(nodes);
  const reachable = reachableFrom(startKey, edges);
  for (const node of nodes) {
    if (!reachable.has(node.key)) {
      add(errors, 'error', 'unreachable', node.key, `${label(node.key)} cannot be reached from the start, so no learner would ever see it.`);
    }
  }
  const canFinish = canReachEnding(nodes, edges);
  for (const node of nodes) {
    if (reachable.has(node.key) && !canFinish.has(node.key)) {
      add(errors, 'error', 'dead_end', node.key, `A learner who reaches ${label(node.key)} cannot get to an ending.`);
    }
  }

  for (const problem of contentProblems(nodes)) {
    const level = problem.strict && !strict ? 'warning' : problem.level;
    add(level === 'error' ? errors : warnings, level, problem.code, problem.node, problem.message);
  }

  const paths = enumeratePaths(nodes);
  const lengths = paths.map((p) => p.length);
  const endingsReached = new Set(paths.map((p) => p[p.length - 1]));

  return {
    errors,
    warnings,
    stats: {
      nodes: nodes.length,
      screens: nodes.filter((n) => n.type === 'text').length,
      decisions: nodes.filter((n) => n.type === 'branching_question').length,
      endings: endings.length,
      paths: paths.length,
      paths_capped: paths.length >= PATH_CAP,
      longest_path: lengths.length ? Math.max(...lengths) : 0,
      shortest_path: lengths.length ? Math.min(...lengths) : 0,
      endings_reached: endingsReached.size,
      acyclic: isAcyclic(edges),
    },
  };
}

// ---------------------------------------------------------------------------
// Scoring
// ---------------------------------------------------------------------------

/** What a full-marks attempt is worth: the best ending. Unscored scenarios are not marked. */
export function maxScore(scenario: BsScenario): number {
  if (scenario.scoring === 'no-score') return 0;
  return scenario.nodes.reduce((best, n) => (n.type === 'ending' ? Math.max(best, n.score) : best), 0);
}

export interface BsOutcome {
  score: number;
  max: number;
  percent: number;
  /** Null when the scenario is not marked: there is nothing to pass. */
  passed: boolean | null;
}

export function outcomeOf(scenario: BsScenario, endingKey: string | null): BsOutcome {
  const max = maxScore(scenario);
  const ending = scenario.nodes.find((n) => n.key === endingKey && n.type === 'ending');
  const score = scenario.scoring === 'no-score' || !ending ? 0 : ending.score;
  const percent = max > 0 ? Math.round((score / max) * 100) : 0;

  return { score, max, percent, passed: max > 0 ? percent >= scenario.passPercentage : null };
}

// ---------------------------------------------------------------------------
// Choice order
// ---------------------------------------------------------------------------

/** A small deterministic generator, so the same attempt shows the same order on back-and-forward. */
function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hashOf(text: string): number {
  let h = 2166136261;
  for (let i = 0; i < text.length; i++) {
    h ^= text.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return h >>> 0;
}

/**
 * A decision's choices in the order to show them, with each one's ORIGINAL
 * index so choosing reports the right choice whatever order it was shown in.
 *
 * Shuffled only when the scenario asks (`randomizeChoices`), and by a seed
 * derived from the node and the attempt, never by `Math.random()` at render.
 */
export function orderedChoices(node: BsNode, randomize: boolean, seed: number): { choice: BsChoice; index: number }[] {
  const items = node.choices.map((choice, index) => ({ choice, index }));
  if (!randomize) return items;

  const random = mulberry32(hashOf(node.key) ^ seed);
  for (let i = items.length - 1; i > 0; i--) {
    const j = Math.floor(random() * (i + 1));
    [items[i], items[j]] = [items[j], items[i]];
  }
  return items;
}

// ---------------------------------------------------------------------------
// The player's state machine
// ---------------------------------------------------------------------------

export type Phase = 'start' | 'node' | 'feedback' | 'end';

export interface Visit {
  nodeKey: string;
  /** The choice taken on a decision; null on a screen. */
  choiceIndex: number | null;
}

export interface PlayState {
  phase: Phase;
  nodeKey: string | null;
  /** Every step already left, in order. */
  trail: Visit[];
  /** On a decision, the choice just made and being explained. */
  pending: number | null;
  endingKey: string | null;
  /** Endings reached in this session, across restarts. */
  found: string[];
  /** The path led somewhere that is not there (a broken scenario). */
  stuck: boolean;
}

export function begin(found: string[] = []): PlayState {
  return { phase: 'start', nodeKey: null, trail: [], pending: null, endingKey: null, found, stuck: false };
}

function nodeAt(scenario: BsScenario, key: string | null): BsNode | undefined {
  return key == null ? undefined : scenario.nodes.find((n) => n.key === key);
}

/** Put the learner on a node — or, if it is an ending, at the end. */
function land(scenario: BsScenario, state: PlayState, key: string | null): PlayState {
  const node = nodeAt(scenario, key);
  if (!node) {
    // A link to nothing. The editor and the publish check refuse this; if one
    // gets here anyway the learner is told, not left on a blank screen.
    return { ...state, phase: 'end', nodeKey: null, pending: null, endingKey: null, stuck: true };
  }
  if (node.type === 'ending') {
    return {
      ...state,
      phase: 'end',
      nodeKey: node.key,
      pending: null,
      endingKey: node.key,
      found: state.found.includes(node.key) ? state.found : [...state.found, node.key],
      stuck: false,
    };
  }
  return { ...state, phase: 'node', nodeKey: node.key, pending: null, endingKey: null, stuck: false };
}

/** Leave the start screen for the first node. */
export function start(scenario: BsScenario, state: PlayState): PlayState {
  if (scenario.nodes.length === 0) return { ...state, phase: 'end', stuck: true };
  return land(scenario, { ...state, trail: [] }, scenario.nodes[0].key);
}

/** "Continue" on a screen. */
export function proceed(scenario: BsScenario, state: PlayState): PlayState {
  const node = nodeAt(scenario, state.nodeKey);
  if (state.phase !== 'node' || !node || node.type !== 'text') return state;
  return land(scenario, { ...state, trail: [...state.trail, { nodeKey: node.key, choiceIndex: null }] }, node.next);
}

/** A choice made on a decision: show what it led to before moving on. */
export function choose(scenario: BsScenario, state: PlayState, choiceIndex: number): PlayState {
  const node = nodeAt(scenario, state.nodeKey);
  if (state.phase !== 'node' || !node || node.type !== 'branching_question' || !node.choices[choiceIndex]) return state;
  return { ...state, phase: 'feedback', pending: choiceIndex };
}

/** "Continue" from a choice's feedback. */
export function continueFromFeedback(scenario: BsScenario, state: PlayState): PlayState {
  const node = nodeAt(scenario, state.nodeKey);
  if (state.phase !== 'feedback' || !node || state.pending == null) return state;
  const choice = node.choices[state.pending];
  if (!choice) return state;
  return land(scenario, { ...state, trail: [...state.trail, { nodeKey: node.key, choiceIndex: state.pending }] }, choice.next);
}

export function canGoBack(scenario: BsScenario, state: PlayState): boolean {
  if (!scenario.backNavigation) return false;
  if (state.phase === 'feedback') return true;
  if (state.phase === 'start') return false;
  return state.trail.length > 0;
}

/**
 * One step back. From a choice's feedback, back to the decision (unchosen);
 * from a node or an ending, to the node before it.
 */
export function back(scenario: BsScenario, state: PlayState): PlayState {
  if (!canGoBack(scenario, state)) return state;
  if (state.phase === 'feedback') return { ...state, phase: 'node', pending: null };

  const trail = state.trail.slice(0, -1);
  const last = state.trail[state.trail.length - 1];
  return { ...state, phase: 'node', nodeKey: last.nodeKey, trail, pending: null, endingKey: null, stuck: false };
}

/** "Try again": straight to the first node, remembering which endings were found. */
export function restart(scenario: BsScenario, state: PlayState): PlayState {
  return start(scenario, begin(state.found));
}

// ---------------------------------------------------------------------------
// Reading the attempt back
// ---------------------------------------------------------------------------

export interface RecapEntry {
  nodeKey: string;
  title: string;
  question: string;
  choiceText: string;
  quality: BsQuality | null;
  feedbackTitle: string;
}

/** The decisions made on this attempt, in order: what the learner chose and how sound it was. */
export function recap(scenario: BsScenario, state: PlayState): RecapEntry[] {
  const out: RecapEntry[] = [];
  for (const visit of state.trail) {
    if (visit.choiceIndex == null) continue;
    const node = nodeAt(scenario, visit.nodeKey);
    const choice = node?.choices[visit.choiceIndex];
    if (!node || !choice) continue;
    out.push({
      nodeKey: node.key,
      title: node.title,
      question: plainText(node.body),
      choiceText: choice.text,
      quality: choice.quality,
      feedbackTitle: plainText(choice.feedbackTitle),
    });
  }
  return out;
}

export function qualityCounts(entries: RecapEntry[]): Record<BsQuality | 'unrated', number> {
  const counts: Record<BsQuality | 'unrated', number> = { best: 0, partial: 0, misstep: 0, unrated: 0 };
  for (const entry of entries) counts[entry.quality ?? 'unrated']++;
  return counts;
}

/** Endings, best first, for the "you found 2 of 4" line. */
export function endingsOf(scenario: BsScenario): BsNode[] {
  return scenario.nodes.filter((n) => n.type === 'ending').sort((a, b) => b.score - a.score);
}

/** The step number a learner is on (1-based), counting the screen they are looking at. */
export function stepNumber(state: PlayState): number {
  return state.trail.length + (state.phase === 'start' ? 0 : 1);
}

// ---------------------------------------------------------------------------
// How long it takes
// ---------------------------------------------------------------------------

/** Words a school student reads in a minute, at a careful pace. */
const WORDS_PER_MINUTE = 130;

/** Seconds of thought each decision is worth on top of reading it. */
const SECONDS_PER_DECISION = 25;

/**
 * About how long one pass takes, in whole minutes (at least 1).
 *
 * Measured on a TYPICAL path -- the median-length one -- not the longest or the
 * sum of everything: a learner never reads the whole tree, and quoting the
 * whole tree would put students off a scenario they would finish in ten
 * minutes. Said as "about", because it is an estimate of reading and not a
 * measurement of anyone.
 */
export function estimateMinutes(scenario: BsScenario): number {
  const paths = enumeratePaths(scenario.nodes, 500);
  if (paths.length === 0) return 1;

  const byKey = new Map(scenario.nodes.map((n) => [n.key, n]));
  const words = (path: string[]) =>
    path.reduce((sum, key) => {
      const node = byKey.get(key);
      if (!node) return sum;
      const choiceWords = node.type === 'branching_question' ? Math.max(...node.choices.map((c) => plainText(c.feedbackText).split(/\s+/).filter(Boolean).length), 0) : 0;
      return sum + plainText(node.body).split(/\s+/).filter(Boolean).length + choiceWords;
    }, 0);
  const decisions = (path: string[]) => path.filter((k) => byKey.get(k)?.type === 'branching_question').length;

  const typical = [...paths].sort((a, b) => words(a) - words(b))[Math.floor(paths.length / 2)];
  const seconds = (words(typical) / WORDS_PER_MINUTE) * 60 + decisions(typical) * SECONDS_PER_DECISION;

  return Math.max(1, Math.round(seconds / 60));
}
